import java.io.*;

class Solution {
    public int findMinFibonacciNumbers(int k) {
        int a = 1, b = 1;
        while (b <= k) {
            int next = a + b;
            a = b;
            b = next;
        }

        int ans = 0;
        while (k > 0) {
            if (a <= k) {
                k -= a;
                ans++;
            }
            int next = a;
            a = b - a;
            b = next;
        }
        return ans;
    }
}

